INSERT INTO operate_log (
    uuid, user_id, company_id, module_name, operate_type, operate_desc,
    operate_time, operate_record, new_record, is_del
) VALUES (
             CAST(#{uuid} AS uuid), #{userId}, #{companyId}, #{moduleName}, #{operateType}, #{operateDesc},
             #{operateTime}, #{operateRecord}, #{newRecord}, #{isDel}
         )
